// Bundles the built-in skills at build time: every apps/server/skills/*/SKILL.md becomes one entry
// of src/skills/builtin.gen.ts. Run `bun scripts/gen-skills.ts` after editing a skill; a test fails
// when the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const root = join(import.meta.dir, "..")
const dir = join(root, "skills")
const entries = readdirSync(dir, { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => d.name)
  .sort()
  .map((name) => [name, readFileSync(join(dir, name, "SKILL.md"), "utf8")] as const)
export const generated = `// Generated by scripts/gen-skills.ts from apps/server/skills/*/SKILL.md. Do not edit.\nexport const BUILTIN_SKILLS: readonly (readonly [string, string])[] = ${JSON.stringify(entries, null, 2)}\n`
if (import.meta.main) writeFileSync(join(root, "src/skills/builtin.gen.ts"), generated)
